When('I check whether editTodo guards against calling removeTodo for already-removed todos', function () {
  const source = this.appSource;
  // The anti-pattern: editTodo unconditionally calls removeTodo(id) when newTitle
  // is empty, even if the todo has already been removed from the model (e.g. via
  // a re-entrant blur call).
  //
  // The fix: at the top of editTodo, call findTodo(id) and return early if the
  // todo no longer exists in the model, BEFORE trimming and checking for empty.
  // This prevents removeTodo(id) and render() from being called re-entrantly
  // when the todo was already removed by the outer execution.
  //
  // Strategy: extract the editTodo function body and check whether there is a
  // findTodo call that guards the empty-title branch.
  const editTodoMatch = source.match(/function\s+editTodo\s*\([^)]*\)\s*\{([\s\S]*?)\n  \}/);
  if (!editTodoMatch) {
    this.editTodoGuardsReentrant = false;
    return;
  }
  const editBody = editTodoMatch[1];

  // Check if the very first thing editTodo does is call findTodo and return
  // if not found. Pattern:
  //   var todo = findTodo(id);
  //   if (!todo) return;
  const hasEarlyFindTodo = /var\s+\w+\s*=\s*findTodo\s*\(\s*\w+\s*\)/.test(editBody);
  const hasEarlyReturn = /if\s*\(\s*!\s*\w+\s*\)\s*return/.test(editBody);

  // Check that the early guard is BEFORE the call to removeTodo
  const removeTodoCallIndex = editBody.indexOf('removeTodo(');
  const findTodoCallIndex = editBody.indexOf('findTodo(');
  if (findTodoCallIndex === -1) {
    this.editTodoGuardsReentrant = false;
    return;
  }
  if (removeTodoCallIndex === -1) {
    this.editTodoGuardsReentrant = true; // no removeTodo call → not vulnerable
    return;
  }

  // The early guard must: call findTodo, check !result, return, all BEFORE removeTodo
  this.editTodoGuardsReentrant = hasEarlyFindTodo && hasEarlyReturn &&
    findTodoCallIndex < removeTodoCallIndex;
});

